class BufferFullException(BufferError):
    """Exception raised when CircularBuffer is full.

    message: explanation of the error.

    """
    def __init__(self, message):
        super().__init__(message)


class BufferEmptyException(BufferError):
    """Exception raised when CircularBuffer is empty.

    message: explanation of the error.

    """
    def __init__(self, message):
        super().__init__(message)


class CircularBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be a positive integer")
        self._capacity = capacity
        self._buffer = [None] * capacity
        self._head = 0  # index of oldest element
        self._tail = 0  # index where next write will occur
        self._size = 0

    def read(self):
        if self._size == 0:
            raise BufferEmptyException("Circular buffer is empty")
        value = self._buffer[self._head]
        self._buffer[self._head] = None
        self._head = (self._head + 1) % self._capacity
        self._size -= 1
        return value

    def write(self, data):
        if self._size == self._capacity:
            raise BufferFullException("Circular buffer is full")
        self._buffer[self._tail] = data
        self._tail = (self._tail + 1) % self._capacity
        self._size += 1

    def overwrite(self, data):
        if self._size == self._capacity:
            # Overwrite the oldest element: write at tail (which equals head when full),
            # advance both head and tail so the oldest element is dropped.
            self._buffer[self._tail] = data
            self._tail = (self._tail + 1) % self._capacity
            self._head = (self._head + 1) % self._capacity
            # size remains capacity
        else:
            self.write(data)

    def clear(self):
        self._buffer = [None] * self._capacity
        self._head = 0
        self._tail = 0
        self._size = 0
